DROP TABLE IF EXISTS formula1;

CREATE TABLE formula1 (
    resultId INT,
    grid INT,
    positionOrder INT,
    cumulPoints DOUBLE,
    points DOUBLE,
    year INT,
    round INT,
    circuit VARCHAR(255),
    driverName VARCHAR(255),
    driverAge INT,
    constructorName VARCHAR(255),
    driverCountry VARCHAR(100),
    constructorCountry VARCHAR(100),
    driverImage VARCHAR(255),
    constructorImage VARCHAR(255)
);





























